import React from 'react';
import { Typography, Paper, Box, Tabs, Tab } from '@mui/material';

function TabPanel(props) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`settings-tabpanel-${index}`}
      aria-labelledby={`settings-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box sx={{ p: 3 }}>
          {children}
        </Box>
      )}
    </div>
  );
}

const AdminSettings = () => {
  const [value, setValue] = React.useState(0);

  const handleChange = (event, newValue) => {
    setValue(newValue);
  };

  return (
    <Box>
      <Typography variant="h4" component="h1" gutterBottom>
        Settings
      </Typography>
      <Paper elevation={0} sx={{ backgroundColor: 'background.paper' }}>
        <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
          <Tabs value={value} onChange={handleChange} aria-label="settings tabs">
            <Tab label="Profile" />
            <Tab label="Account" />
            <Tab label="Security" />
          </Tabs>
        </Box>

        <TabPanel value={value} index={0}>
          <Typography variant="h6" gutterBottom>Profile Settings</Typography>
          <Typography>Update your profile information here.</Typography>
          {/* Add profile settings form here */}
        </TabPanel>

        <TabPanel value={value} index={1}>
          <Typography variant="h6" gutterBottom>Account Settings</Typography>
          <Typography>Manage your account preferences.</Typography>
          {/* Add account settings here */}
        </TabPanel>

        <TabPanel value={value} index={2}>
          <Typography variant="h6" gutterBottom>Security Settings</Typography>
          <Typography>Update your password and security settings.</Typography>
          {/* Add security settings here */}
        </TabPanel>
      </Paper>
    </Box>
  );
};

export default AdminSettings;
